<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/includes/functions.php';
$u=requireRole('user','member','admin');
$lang=lang();
$sql="SELECT e.*, (SELECT COUNT(*) FROM event_rsvps r WHERE r.event_id=e.id) AS attendee_count, (SELECT COUNT(*) FROM event_rsvps mine WHERE mine.event_id=e.id AND mine.user_id=?) AS is_registered FROM events e WHERE e.is_published=1 AND e.event_date>=CURDATE() ORDER BY e.event_date ASC,e.event_time ASC LIMIT 60";
$s=db()->prepare($sql);$s->execute([$u['id']]);$events=$s->fetchAll();
$pageTitle='Events';require dirname(__DIR__).'/includes/header.php';
?>
<section class="section"><div class="container"><div class="portal-page-heading"><div><p class="eyebrow">STAY INVOLVED</p><h1 class="section-title">Events and activities</h1><p class="copy">Discover what's coming up, check the details and manage your registration through each event page.</p></div><a class="btn ghost" href="<?=APP_URL?>/events.php">Public events page ↗</a></div>
<?php if($events):?><div class="grid-3 member-event-grid"><?php foreach($events as $ev):?><article class="card member-event-card"><div class="card-media"><?php if($ev['featured_image']):?><img loading="lazy" src="<?=e($ev['featured_image'])?>" alt="<?=e(localTitle($ev,$lang))?>"><?php else:?><div class="media-placeholder media-event" aria-hidden="true"><span>ATACJL · EVENT</span></div><?php endif;?></div><div class="card-body"><div class="meta-row"><span class="tag"><?=e(date('D, M j, Y',strtotime($ev['event_date'])))?></span><?php if((int)$ev['is_registered']):?><span class="status-chip status-approved">Registered</span><?php endif;?></div><h3><?=e(localTitle($ev,$lang))?></h3><p><?=e(mb_strimwidth(strip_tags(localDescription($ev,$lang)),0,140,'…'))?></p><div class="event-facts"><span>⌖ <?=e($ev['location'])?></span><span>◷ <?=e(substr((string)$ev['event_time'],0,5))?></span><?php if($ev['capacity']):?><span>♧ <?=max(0,(int)$ev['capacity']-(int)$ev['attendee_count'])?> places left</span><?php endif;?></div><a class="btn <?=((int)$ev['is_registered'])?'ghost':'primary'?>" href="<?=APP_URL?>/event-detail.php?id=<?=$ev['id']?>"><?=((int)$ev['is_registered'])?'View registration':'View event & RSVP'?></a></div></article><?php endforeach;?></div><?php else:?><div class="empty-state"><span class="empty-icon">⌁</span><h2>No upcoming events</h2><p>There are no published events scheduled at the moment. Check back soon for new activities.</p><a class="btn ghost" href="<?=APP_URL?>/index.php">Back to ATACJL home</a></div><?php endif;?></div></section>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
